11	const BASE_PREMIUM: Record<string, number> = {
12	  sword: 100,
13	  amulet: 60,
14	  staff: 80,
15	  potion: 40,
16	  rune: 25,
17	};
18	
19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE = 0.1;
21	
22	const itemPremium = (item: { type: string }): number => {
23	  const base = BASE_PREMIUM[item.type];
24	  // Keep as `base + base * rate`, not `base * (1 + rate)`: the additive form
25	  // avoids IEEE-754 drift that would otherwise round wrong under Math.ceil.
26	  return base + base * FIRST_INSURANCE_SURCHARGE;
27	};
28	
29	const quotePremium = (items: { type: string }[]): number => {
30	  const itemsTotal = items.reduce((sum, item) => sum + itemPremium(item), 0);
31	  return Math.ceil(itemsTotal + PROCESSING_FEE);
32	};
33	
34	export const runScenario = (scenario: Scenario): { results: unknown[] } => {
35	  const results = scenario.steps.map((step) => ({
36	    premium: quotePremium(step.items),
37	  }));
38	  return { results };
39	};
